// ═══════════════════════════════════════
// PHASE 1: RETRIEVAL PLANNING
// ═══════════════════════════════════════
const body = $input.first().json.body || {};

const task = body.task || body.query || body.question || '';
const brand = body.brand || '';
const product = body.product || '';
const audience = body.audience || '';
const platform = body.platform || '';
const timeSensitivity = body.timeSensitivity || 'medium';
const confidenceRequirement = body.confidenceRequirement || 0.75;

// تحديد المجالات المعرفية المطلوبة
const knowledgeRequired = [];
if (task.toLowerCase().includes('campaign') || task.toLowerCase().includes('حملة')) {
  knowledgeRequired.push('Campaign History', 'Performance Analytics', 'Audience Knowledge');
}
if (task.toLowerCase().includes('content') || task.toLowerCase().includes('محتوى')) {
  knowledgeRequired.push('Historical Content', 'Trend Intelligence', 'Brand Knowledge');
}
if (task.toLowerCase().includes('competitor') || task.toLowerCase().includes('منافس')) {
  knowledgeRequired.push('Competitor Intelligence', 'Market Intelligence');
}
if (task.toLowerCase().includes('audience') || task.toLowerCase().includes('جمهور')) {
  knowledgeRequired.push('Audience Knowledge', 'Product Knowledge');
}
if (knowledgeRequired.length === 0) {
  knowledgeRequired.push('Brand Knowledge', 'Product Knowledge', 'Audience Knowledge', 'Trend Intelligence');
}

// تحديد المصادر
const sourcesRequired = [];
if (brand) sourcesRequired.push('brand_knowledge');
if (product) sourcesRequired.push('product_knowledge');
if (audience) sourcesRequired.push('audience_segments');
sourcesRequired.push('trend_intelligence', 'competitor_intelligence', 'campaign_history', 'performance_analytics');

const plan = {
  task,
  brand,
  product,
  audience,
  platform,
  knowledge_required: knowledgeRequired,
  sources_required: sourcesRequired,
  time_sensitivity: timeSensitivity,
  freshness_requirement: timeSensitivity === 'high' ? 'last_7_days' : 'last_30_days',
  confidence_requirement: confidenceRequirement,
  session_id: body.sessionId || Date.now().toString(),
  timestamp: new Date().toISOString()
};

return [{ json: plan }];

// ═══════════════════════════════════════
// PHASE 3: FILTER + RERANK + GRADE
// ═══════════════════════════════════════
const plan = $input.first().json;

// جمع جميع النتائج من المصادر الثلاثة
const memoryResults = $items('Retrieve Memory').map(item => ({
  source: 'memory',
  type: item.json.knowledge_type || 'unknown',
  content: item.json.insight || '',
  confidence: item.json.confidence || 0.5,
  authority: 0.9, // الذاكرة الداخلية ذات مصداقية عالية
  freshness: item.json.created_at ? (new Date() - new Date(item.json.created_at)) / (1000 * 60 * 60 * 24) : 30,
  business_fit: 0.8,
  performance_relevance: item.json.source_campaigns ? 0.85 : 0.5
}));

const externalResults = ($items('Retrieve External')[0]?.json?.results || []).map(r => ({
  source: 'external',
  type: r.type || 'external_research',
  content: r.content || r.snippet || '',
  confidence: r.confidence || 0.6,
  authority: r.authority || 0.6,
  freshness: r.freshness_days || 7,
  business_fit: r.business_fit || 0.5,
  performance_relevance: r.performance_relevance || 0.4
}));

const performanceResults = $items('Retrieve Performance').map(item => ({
  source: 'performance',
  type: 'performance_analytics',
  content: `Campaign: ${item.json.campaign_name} | Platform: ${item.json.platform} | CTR: ${item.json.ctr}% | ROAS: ${item.json.roas} | Creative: ${item.json.creative_angle}`,
  confidence: item.json.roas > 3 ? 0.9 : item.json.roas > 1.5 ? 0.75 : 0.5,
  authority: 0.95, // بيانات الأداء هي الأكثر مصداقية
  freshness: item.json.created_at ? (new Date() - new Date(item.json.created_at)) / (1000 * 60 * 60 * 24) : 30,
  business_fit: 0.9,
  performance_relevance: 1.0
}));

const allResults = [...memoryResults, ...externalResults, ...performanceResults];

// حساب درجة المركبة لكل عنصر
const scored = allResults.map(item => {
  const relevance = item.confidence;
  const authority = item.authority;
  const freshness = Math.max(0, 1 - (item.freshness / 30)); // تناسب عكسي مع العمر
  const businessFit = item.business_fit;
  const perfRel = item.performance_relevance;

  const compositeScore = (
    relevance * 0.30 +
    authority * 0.25 +
    freshness * 0.15 +
    businessFit * 0.15 +
    perfRel * 0.15
  );

  return { ...item, composite_score: parseFloat(compositeScore.toFixed(3)) };
});

// تصفية: رفض العناصر ذات الدرجة المنخفضة
const threshold = plan.confidence_requirement || 0.5;
const filtered = scored.filter(item => item.composite_score >= threshold);

// إعادة الترتيب
const reranked = filtered.sort((a, b) => b.composite_score - a.composite_score).slice(0, 10);

// تحديد ما إذا كانت الأدلة كافية
const evidenceSufficient = reranked.length >= 3 && reranked[0].composite_score >= 0.7;
const missingDomains = plan.knowledge_required.filter(k => 
  !reranked.some(r => r.type.toLowerCase().includes(k.toLowerCase()))
);

return [{
  json: {
    ...plan,
    retrieved_items: reranked,
    total_items: allResults.length,
    filtered_items: reranked.length,
    evidence_sufficient: evidenceSufficient,
    confidence: reranked.length > 0 ? reranked[0].composite_score : 0,
    missing_information: missingDomains,
    conflicts: [],
    timestamp: new Date().toISOString()
  }
}];

// ═══════════════════════════════════════
// PHASE 4: VERIFY + REASON + SYNTHESIZE
// ═══════════════════════════════════════
const data = $input.first().json;
const items = data.retrieved_items || [];

// التحقق من التعارضات
const conflicts = [];
const byType = {};
items.forEach(item => {
  if (!byType[item.type]) byType[item.type] = [];
  byType[item.type].push(item);
});

for (const [type, typeItems] of Object.entries(byType)) {
  if (typeItems.length >= 2) {
    const contents = typeItems.map(t => t.content.toLowerCase());
    // كشف تعارض بسيط: إذا كانت هناك كلمات متضادة
    const positive = contents.some(c => c.includes('increase') || c.includes('grow') || c.includes('best'));
    const negative = contents.some(c => c.includes('decrease') || c.includes('drop') || c.includes('worst'));
    if (positive && negative) {
      conflicts.push({
        domain: type,
        viewpoint_a: typeItems[0].content.substring(0, 200),
        viewpoint_b: typeItems[1].content.substring(0, 200),
        resolution: 'preserve_both'
      });
    }
  }
}

// بناء سياق للتوليف
const context = items.map((item, i) => 
  `[${i+1}] Source: ${item.source} | Type: ${item.type} | Score: ${item.composite_score}\n${item.content}`
).join('\n\n');

const systemPrompt = `You are AGENTIC-RAG-Ω, a marketing intelligence engine.
Analyze the retrieved evidence and synthesize a strategic marketing recommendation.

RULES:
- Base your answer ONLY on the provided evidence.
- If evidence is insufficient, say so explicitly.
- If conflicts exist, present both viewpoints.
- Cite sources by number [1], [2], etc.
- Return confidence level (0.0-1.0).
- Structure: Summary → Evidence → Recommendation → Confidence → Missing Info`;

const userPrompt = `TASK: ${data.task}
BRAND: ${data.brand || 'N/A'}
PRODUCT: ${data.product || 'N/A'}
AUDIENCE: ${data.audience || 'N/A'}
PLATFORM: ${data.platform || 'N/A'}

EVIDENCE:
${context}

CONFLICTS: ${conflicts.length > 0 ? JSON.stringify(conflicts) : 'None detected'}

MISSING DOMAINS: ${data.missing_information?.join(', ') || 'None'}

Synthesize a marketing recommendation.`;

return [{
  json: {
    ...data,
    conflicts,
    synthesis_input: { systemPrompt, userPrompt },
    timestamp: new Date().toISOString()
  }
}];

// ═══════════════════════════════════════
// PHASE 6: STRUCTURE OUTPUT
// ═══════════════════════════════════════
const aiResponse = $input.first().json;
const plan = $items('1. Retrieval Planning')[0].json;
const graded = $items('3. Filter / Rerank / Grade')[0].json;

return [{
  json: {
    retrieval_plan: {
      task: plan.task,
      knowledge_required: plan.knowledge_required,
      sources_required: plan.sources_required,
      time_sensitivity: plan.time_sensitivity,
      confidence_requirement: plan.confidence_requirement
    },
    knowledge_found: graded.retrieved_items.map(item => ({
      source: item.source,
      type: item.type,
      content_preview: item.content.substring(0, 300),
      composite_score: item.composite_score
    })),
    evidence: {
      total_items: graded.total_items,
      filtered_items: graded.filtered_items,
      evidence_sufficient: graded.evidence_sufficient,
      confidence: graded.confidence
    },
    confidence: graded.confidence,
    missing_information: graded.missing_information,
    conflicts: graded.conflicts,
    recommendation: aiResponse.output || aiResponse.text || aiResponse.response || aiResponse,
    memory_update: graded.evidence_sufficient && graded.confidence >= 0.75 ? 'STORE' : 'DO NOT STORE',
    session_id: plan.session_id,
    timestamp: new Date().toISOString()
  }
}];

// معالجة الأخطاء
const error = $input.first().json;
return [{
  json: {
    success: false,
    error: error.message || 'AGENTIC-RAG-Ω Error',
    phase: error.phase || 'unknown',
    timestamp: new Date().toISOString()
  }
}];
